// Reinterpreting Memory Block as Different Structure
typedef struct { uint32_t a; uint16_t b; } DataA;
typedef struct { char raw[6]; } DataB;
uint8_t memory[6] = {1, 0, 0, 0, 2, 0};
DataA* data_a = (DataA*)memory;
DataB* data_b = (DataB*)memory;
// Access through new types
uint32_t val_a = data_a->a;
char first_byte = data_b->raw[0];

// Pointer arithmetic for specific byte offset access
#define DATA_SIZE 1024
uint8_t buffer[DATA_SIZE];
uint32_t* base_ptr = (uint32_t*)buffer;
// Access the 12th 32-bit integer (offset 48 bytes)
uint32_t target_val = *(base_ptr + 11);
// Byte-level manipulation at byte offset 50
uint8_t* byte_ptr = (uint8_t*)buffer;
*(byte_ptr + 50) = 0xFF;

// Type punning via union
union RegisterAccess {
    uint32_t full_word;
    struct { uint16_t low; uint16_t high; } parts;
};
RegisterAccess reg;
reg.full_word = 0xAABBCCDD;
uint16_t low_part = reg.parts.low; // CC DD (on little-endian)

// Aligning pointers manually
#define ALIGNMENT 16
char raw_memory[100 + ALIGNMENT];
uintptr_t mask = ALIGNMENT - 1;
uintptr_t address = (uintptr_t)raw_memory;
uintptr_t aligned_addr = (address + mask) & ~mask;
void* aligned_ptr = (void*)aligned_addr;
